-- public.game_mode_leaderboard
-- Generated by scripts/schema-snapshot.mjs from project heuhqqoxyggawuckxocp. Do not edit by hand.

-- SECURITY DEFINER; API roles that may call it: authenticated, service_role
CREATE OR REPLACE FUNCTION public.game_mode_leaderboard(p_mode text, p_region text, p_event uuid DEFAULT NULL::uuid, p_daily boolean DEFAULT false, p_limit integer DEFAULT 25)
 RETURNS TABLE(id uuid, player_id uuid, name text, photo_url text, correct integer, total integer, time_ms integer, created_at timestamp with time zone, day_key integer, streak integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with scoped as (
    select g.*
      from public.game_scores g
      join public.profiles p on p.id = g.player_id
     where g.mode = p_mode
       and g.region = p_region
       and coalesce(p.is_test, false) = false
       and p.deletion_requested_at is null
       -- An event board is that event's rounds; the ordinary board is
       -- everything that does not belong to one.
       and (case when p_event is null then g.event_id is null else g.event_id = p_event end)
       -- A daily puzzle ranks TODAY's solves: everybody had the same puzzle,
       -- and it refreshes at midnight UK time.
       and (not p_daily or g.created_at >= date_trunc('day', now() at time zone 'Europe/London') at time zone 'Europe/London')
  ),
  best as (
    select distinct on (s.player_id) s.*
      from scoped s
     order by s.player_id, s.correct desc, s.time_ms asc, s.created_at asc
  ),
  -- The daily play streak for this mode, per player, on the same
  -- gaps-and-islands shape `streak_leaderboard` uses. Only the players on the
  -- board are computed, and only from rows that actually stamped a day.
  days as (
    select g.player_id as pid, public.game_day(g.day_key, g.created_at) as d
      from public.game_scores g
     where g.mode = p_mode
       and g.day_key is not null
       and g.player_id in (select player_id from best)
  ),
  islands as (
    select d.pid, d.d, d.d - row_number() over (partition by d.pid order by d.d) as grp
      from (select distinct pid, d from days) d
  ),
  runs as (
    select i.pid, count(*)::int as len, max(i.d) as last_day
      from islands i group by i.pid, i.grp
  ),
  today as (
    select floor(extract(epoch from (now() at time zone 'Europe/London')) / 86400)::int as d
  ),
  current_run as (
    select r.pid, max(r.len) as len
      from runs r, today t
     where r.last_day >= t.d - 1          -- today, or yesterday's grace
     group by r.pid
  )
  select b.id, b.player_id, p.name, p.photo_url,
         b.correct, b.total, b.time_ms, b.created_at, b.day_key,
         coalesce(c.len, 0)::int as streak
    from best b
    join public.profiles p on p.id = b.player_id
    left join current_run c on c.pid = b.player_id
   order by b.correct desc, b.time_ms asc, p.name asc
   limit greatest(1, least(p_limit, 100));
$function$;
